  background: var(--dash-tabulator-header);
  color: var(--dash-tabulator-text);
  font-weight: 600;
}

.dash-tabulator .tabulator-header .tabulator-col {
  border-right: 1px solid var(--dash-tabulator-border);
  background: transparent;
}

.dash-tabulator .tabulator-header .tabulator-col:last-child,
.dash-tabulator .tabulator-row .tabulator-cell:last-child {
