.dash-tabulator .tabulator-header-filter select {
  width: 100%;
  min-height: 2rem;
  border: 1px solid var(--dash-tabulator-border);
  border-radius: var(--mantine-radius-sm, 0.25rem);
  background: var(--dash-tabulator-body);
  color: var(--dash-tabulator-text);
  font: inherit;
  padding: 0.25rem 0.5rem;
  outline: none;
}

.dash-tabulator .tabulator-header-filter input:focus,
.dash-tabulator .tabulator-header-filter select:focus {
  border-color: var(--dash-tabulator-primary);
}

.dash-tabulator .tabulator-tableholder,
.dash-tabulator .tabulator-table {
  background: var(--dash-tabulator-body);
}

.dash-tabulator .tabulator-row {
  min-height: 2.5rem;
  border-bottom: 1px solid var(--dash-tabulator-border);
  background: var(--dash-tabulator-body);
  color: var(--dash-tabulator-text);
}

.dash-tabulator .tabulator-row:hover {
  background: var(--dash-tabulator-hover);
}

.dash-tabulator .tabulator-row .tabulator-cell {
  border-right: 1px solid transparent;
  padding: 0.625rem 0.75rem;
}

.dash-tabulator .tabulator-group {
  border-top: 0;
  border-bottom: 1px solid var(--dash-tabulator-border);
  background: var(--dash-tabulator-header);
  color: var(--dash-tabulator-text);
  font-weight: 600;
  padding: 0.625rem 0.75rem;
}

.dash-tabulator .tabulator-group .tabulator-arrow {
  border-left-color: var(--dash-tabulator-dimmed);
}

.dash-tabulator .tabulator-calcs-holder,
.dash-tabulator .tabulator-row.tabulator-calcs {
  border-top: 1px solid var(--dash-tabulator-border);
  background: var(--dash-tabulator-header);
  color: var(--dash-tabulator-text);
  font-weight: 600;
}

.dash-tabulator .tabulator-group span {
  margin-left: 0.5rem;
  color: var(--dash-tabulator-dimmed);
  font-weight: 400;
}

.dash-tabulator .tabulator-placeholder {
  background: var(--dash-tabulator-body);
  color: var(--dash-tabulator-dimmed);
}

.dash-tabulator-sparkline {
  display: block;
  width: 88px;
  height: 24px;
}

.dash-tabulator-sparkline polyline {
  stroke: var(--dash-tabulator-primary);
  stroke-width: 1.75;
  stroke-linecap: round;
  stroke-linejoin: round;
}
